INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(1151, '顶', 'dǐng', '顶起', 'dǐng qǐ', 'ดันขึ้น/ยันขึ้น', '盘古用力顶起天空，顶了好多年。', 'ผานกู่ออกแรงดันฟ้าขึ้น ดันอยู่หลายปี', 'pán gǔ yòng lì dǐng qǐ tiān kōng, dǐng le hǎo duō nián'),
(1152, '徐', 'xú', '徐徐', 'xú xú', 'ช้าๆ/เอื่อยๆ', '风徐徐吹来，吹落了树上的叶子。', 'ลมพัดมาเอื่อยๆ พัดใบไม้บนต้นร่วงลง', 'fēng xú xú chuī lái, chuī luò le shù shàng de yè zi'),
(1153, '尘', 'chén', '灰尘', 'huī chén', 'ฝุ่นละออง', '窗户开了一夜，桌子上满是灰尘。', 'หน้าต่างเปิดทั้งคืน บนโต๊ะเต็มไปด้วยฝุ่น', 'chuāng hù kāi le yí yè, zhuō zi shàng mǎn shì huī chén'),
(1154, '慌', 'huāng', '慌张', 'huāng zhāng', 'ตกใจ/ลนลาน', '我们还有很多时间，不要慌张。', 'เรายังมีเวลาอีกมาก ไม่ต้องลนลาน', 'wǒ men hái yǒu hěn duō shí jiān, bú yào huāng zhāng'),
(1155, '永', 'yǒng', '永远', 'yǒng yuǎn', 'ตลอดไป/ชั่วนิรันดร์', '多希望生活永远这么美好啊！', 'หวังเหลือเกินว่าชีวิตจะดีงามเช่นนี้ตลอดไป!', 'duō xī wàng shēng huó yǒng yuǎn zhè me měi hǎo a'),
(1156, '切', 'qiē', '切菜', 'qiē cài', 'หั่นผัก', '一进家门，我就听到了切菜的声音。', 'พอเข้าประตูบ้าน ฉันก็ได้ยินเสียงหั่นผัก', 'yí jìn jiā mén, wǒ jiù tīng dào le qiē cài de shēng yīn'),
(1157, '碰', 'pèng', '碰到', 'pèng dào', 'ชน/บังเอิญเจอ', '那辆车不小心碰到了路边的大石头。', 'รถคันนั้นเผลอไปชนก้อนหินใหญ่ข้างถนน', 'nà liàng chē bù xiǎo xīn pèng dào le lù biān de dà shí tou'),
(1158, '够', 'gòu', '足够', 'zú gòu', 'เพียงพอ', '这些食物已经足够小蚂蚁过冬了。', 'อาหารพวกนี้เพียงพอให้มดน้อยผ่านฤดูหนาวแล้ว', 'zhè xiē shí wù yǐ jīng zú gòu xiǎo mǎ yǐ guò dōng le'),
(1159, '盏', 'zhǎn', '一盏', 'yì zhǎn', 'หนึ่งดวง (ลักษณนามตะเกียง)', '一盏油灯在黑夜中闪烁着微光。', 'ตะเกียงน้ำมันดวงหนึ่งส่องแสงริบหรี่อยู่ในคืนมืด', 'yì zhǎn yóu dēng zài hēi yè zhōng shǎn shuò zhe wēi guāng'),
(1160, '线', 'xiàn', '毛线', 'máo xiàn', 'ไหมพรม', '我家的小猫非常爱玩毛线团。', 'แมวน้อยที่บ้านฉันชอบเล่นก้อนไหมพรมมาก', 'wǒ jiā de xiǎo māo fēi cháng ài wán máo xiàn tuán'),
(1161, '醉', 'zuì', '喝醉', 'hē zuì', 'เมา (เหล้า)', '这个人喝醉了，坐在地上唱起歌来。', 'คนคนนี้เมาแล้ว นั่งลงกับพื้นแล้วร้องเพลง', 'zhè ge rén hē zuì le, zuò zài dì shàng chàng qǐ gē lái'),
(1162, '印', 'yìn', '脚印', 'jiǎo yìn', 'รอยเท้า', '沙滩上留下了两行明显的脚印。', 'บนหาดทรายทิ้งรอยเท้าไว้สองแถวอย่างชัดเจน', 'shā tān shàng liú xià le liǎng háng míng xiǎn de jiǎo yìn'),
(1163, '灾', 'zāi', '火灾', 'huǒ zāi', 'อัคคีภัย/ไฟไหม้', '每个人都要学习一些火灾安全常识。', 'ทุกคนควรเรียนรู้ความรู้ความปลอดภัยเรื่องอัคคีภัยบ้าง', 'měi gè rén dōu yào xué xí yì xiē huǒ zāi ān quán cháng shí'),
(1164, '含', 'hán', '含着', 'hán zhe', 'อม/คลอ (น้ำตา)', '小女孩的眼睛里含着闪闪的泪花。', 'ในดวงตาของเด็กหญิงคลอด้วยหยาดน้ำตาที่วิบวับ', 'xiǎo nǚ hái de yǎn jīng lǐ hán zhe shǎn shǎn de lèi huā'),
(1165, '汪', 'wāng', '泪汪汪', 'lèi wāng wāng', 'ตาคลอน้ำตา', '他刚哭过，眼里还泪汪汪的。', 'เขาเพิ่งร้องไห้มา ในตายังคลอน้ำตาอยู่เลย', 'tā gāng kū guò, yǎn lǐ hái lèi wāng wāng de'),
(1166, '荣', 'róng', '枯荣', 'kū róng', 'ร่วงโรยและผลิบาน', '离离原上草，一岁一枯荣。', 'หญ้าบนทุ่งกว้างเขียวขจี ปีหนึ่งร่วงโรยผลิบานหนึ่งครั้ง', 'lí lí yuán shàng cǎo, yí suì yì kū róng'),
(1167, '宿', 'sù', '宿舍', 'sù shè', 'หอพัก', '这个宿舍楼里住着一百多人。', 'ในอาคารหอพักหลังนี้มีคนอาศัยอยู่ร้อยกว่าคน', 'zhè ge sù shè lóu lǐ zhù zhe yì bǎi duō rén'),
(1168, '福', 'fú', '幸福', 'xìng fú', 'ความสุข', '人们过上了越来越幸福的生活。', 'ผู้คนมีชีวิตที่มีความสุขมากขึ้นเรื่อยๆ', 'rén men guò shàng le yuè lái yuè xìng fú de shēng huó'),
(1169, '抬', 'tái', '抬起', 'tái qǐ', 'เงย/ยกขึ้น', '她抬起头，发现窗外已洁白一片。', 'เธอเงยหน้าขึ้น พบว่านอกหน้าต่างขาวโพลนไปหมดแล้ว', 'tā tái qǐ tóu, fā xiàn chuāng wài yǐ jié bái yí piàn'),
(1170, '竿', 'gān', '竹竿', 'zhú gān', 'ไม้ไผ่ (ลำ)', '竹竿上落着一只美丽的蜻蜓。', 'บนลำไม้ไผ่มีแมลงปอสวยงามเกาะอยู่ตัวหนึ่ง', 'zhú gān shàng luò zhe yì zhī měi lì de qīng tíng'),
(1171, '洁', 'jié', '清洁', 'qīng jié', 'สะอาด', '经常洗澡可以保持身体的清洁。', 'การอาบน้ำเป็นประจำช่วยรักษาความสะอาดของร่างกาย', 'jīng cháng xǐ zǎo kě yǐ bǎo chí shēn tǐ de qīng jié'),
(1172, '艺', 'yì', '艺术', 'yì shù', 'ศิลปะ', '舞蹈是表现人体美的一门艺术。', 'การเต้นเป็นศิลปะแขนงหนึ่งที่แสดงความงามของร่างกาย', 'wǔ dǎo shì biǎo xiàn rén tǐ měi de yì mén yì shù'),
(1173, '晴', 'qíng', '晴天', 'qíng tiān', 'วันแดดใส/ฟ้าโปร่ง', '昨天一直下雨，今天总算晴天了。', 'เมื่อวานฝนตกทั้งวัน วันนี้ในที่สุดฟ้าก็โปร่ง', 'zuó tiān yì zhí xià yǔ, jīn tiān zǒng suàn qíng tiān le'),
(1174, '朗', 'lǎng', '朗读', 'lǎng dú', 'อ่านออกเสียง', '早晨，他常常在花园里朗读课文。', 'ยามเช้า เขามักอ่านออกเสียงบทเรียนอยู่ในสวน', 'zǎo chén, tā cháng cháng zài huā yuán lǐ lǎng dú kè wén'),
(1175, '品', 'pǐn', '品尝', 'pǐn cháng', 'ชิม/ลิ้มรส', '妈妈做了很多好吃的让客人品尝。', 'แม่ทำอาหารอร่อยๆ มากมายให้แขกได้ชิม', 'mā mā zuò le hěn duō hǎo chī de ràng kè rén pǐn cháng'),
(1176, '浅', 'qiǎn', '浅水', 'qiǎn shuǐ', 'น้ำตื้น', '游泳初学者一定要在浅水区练习。', 'ผู้เริ่มหัดว่ายน้ำต้องฝึกในเขตน้ำตื้นเสมอ', 'yóu yǒng chū xué zhě yí dìng yào zài qiǎn shuǐ qū liàn xí'),
(1177, '盛', 'chéng', '盛饭', 'chéng fàn', 'ตักข้าว', '有的客人不喜欢主人一直给他盛饭。', 'แขกบางคนไม่ชอบให้เจ้าบ้านคอยตักข้าวให้ตลอด', 'yǒu de kè rén bù xǐ huān zhǔ rén yì zhí gěi tā chéng fàn'),
(1178, '纹', 'wén', '花纹', 'huā wén', 'ลวดลาย', '这件衣服上的花纹非常与众不同。', 'ลวดลายบนเสื้อตัวนี้แตกต่างจากคนอื่นอย่างมาก', 'zhè jiàn yī fú shàng de huā wén fēi cháng yǔ zhòng bù tóng'),
(1179, '产', 'chǎn', '生产', 'shēng chǎn', 'ผลิต', '这个工厂生产的东西都是合格品。', 'ของที่โรงงานนี้ผลิตล้วนเป็นสินค้าที่ได้มาตรฐาน', 'zhè ge gōng chǎng shēng chǎn de dōng xi dōu shì hé gé pǐn'),
(1180, '陈', 'chén', '陈旧', 'chén jiù', 'เก่า/ล้าสมัย', '墙边停放着一辆陈旧的自行车。', 'ข้างกำแพงจอดจักรยานเก่าๆ ไว้คันหนึ่ง', 'qiáng biān tíng fàng zhe yí liàng chén jiù de zì xíng chē'),
(1181, '赢', 'yíng', '输赢', 'shū yíng', 'แพ้ชนะ', '只要用心去做了，输赢并不重要。', 'ขอเพียงตั้งใจทำอย่างเต็มที่ แพ้ชนะไม่สำคัญ', 'zhǐ yào yòng xīn qù zuò le, shū yíng bìng bú zhòng yào'),
(1182, '胜', 'shèng', '胜利', 'shèng lì', 'ชัยชนะ', '我军终于取得了战斗的胜利。', 'กองทัพเราได้รับชัยชนะในการรบในที่สุด', 'wǒ jūn zhōng yú qǔ dé le zhàn dòu de shèng lì'),
(1183, '良', 'liáng', '善良', 'shàn liáng', 'ใจดี/มีเมตตา', '她心地善良，经常帮助有困难的人。', 'เธอจิตใจดีงาม มักช่วยเหลือคนที่ลำบากอยู่เสมอ', 'tā xīn dì shàn liáng, jīng cháng bāng zhù yǒu kùn nán de rén'),
(1184, '沿', 'yán', '沿着', 'yán zhe', 'เลียบ/ไปตาม', '泉水沿着山下的洞口流了出来。', 'น้ำพุไหลออกมาตามช่องถ้ำเชิงเขา', 'quán shuǐ yán zhe shān xià de dòng kǒu liú le chū lái'),
(1185, '丛', 'cóng', '草丛', 'cǎo cóng', 'พงหญ้า', '前面没路了，只能在草丛里走了。', 'ข้างหน้าไม่มีทางแล้ว ได้แต่เดินลุยพงหญ้าไป', 'qián miàn méi lù le, zhǐ néng zài cǎo cóng lǐ zǒu le'),
(1186, '厚', 'hòu', '厚厚', 'hòu hòu', 'หนาๆ', '冬天，大家都穿上了厚厚的棉衣。', 'ฤดูหนาว ทุกคนสวมเสื้อนวมหนาๆ กันหมด', 'dōng tiān, dà jiā dōu chuān shàng le hòu hòu de mián yī'),
(1187, '富', 'fù', '富有', 'fù yǒu', 'มั่งมี/ร่ำรวย', '她聪明能干，生活越来越富有。', 'เธอฉลาดและเก่ง ชีวิตยิ่งร่ำรวยขึ้นเรื่อยๆ', 'tā cōng míng néng gàn, shēng huó yuè lái yuè fù yǒu'),
(1188, '涛', 'tāo', '波涛', 'bō tāo', 'คลื่นลูกใหญ่', '小船在大海的波涛中勇往直前。', 'เรือน้อยมุ่งหน้าไปข้างหน้าอย่างกล้าหาญท่ามกลางคลื่นในทะเล', 'xiǎo chuán zài dà hǎi de bō tāo zhōng yǒng wǎng zhí qián'),
(1189, '扎', 'zhā', '扎手', 'zhā shǒu', 'ตำมือ/บาดมือ', '这朵花好扎手，拿的时候要小心！', 'ดอกไม้ดอกนี้ตำมือ ตอนถือต้องระวัง!', 'zhè duǒ huā hǎo zhā shǒu, ná de shí hòu yào xiǎo xīn'),
(1190, '扁', 'biǎn', '扁豆', 'biǎn dòu', 'ถั่วแปบ', '他在地里种了很多扁豆，绿油油的。', 'เขาปลูกถั่วแปบไว้ในไร่มากมาย เขียวขจีไปหมด', 'tā zài dì lǐ zhòng le hěn duō biǎn dòu, lǜ yóu yóu de'),
(1191, '英', 'yīng', '英雄', 'yīng xióng', 'วีรบุรุษ', '他与敌人英勇斗争，真是个大英雄。', 'เขาต่อสู้กับศัตรูอย่างกล้าหาญ เป็นวีรบุรุษผู้ยิ่งใหญ่จริงๆ', 'tā yǔ dí rén yīng yǒng dòu zhēng, zhēn shì gè dà yīng xióng'),
(1192, '雄', 'xióng', '英雄', 'yīng xióng', 'วีรบุรุษ', '人们被他的英雄事迹感动得流泪了。', 'ผู้คนซาบซึ้งกับวีรกรรมของเขาจนหลั่งน้ำตา', 'rén men bèi tā de yīng xióng shì jì gǎn dòng de liú lèi le'),
(1193, '贺', 'hè', '庆贺', 'qìng hè', 'แสดงความยินดี/ฉลอง', '我们来到朋友家为他庆贺生日。', 'พวกเรามาที่บ้านเพื่อนเพื่อฉลองวันเกิดให้เขา', 'wǒ men lái dào péng yǒu jiā wèi tā qìng hè shēng rì'),
(1194, '峡', 'xiá', '峡谷', 'xiá gǔ', 'หุบเขา/โตรกผา', '海洋底部也有高山和峡谷。', 'ใต้ท้องทะเลก็มีภูเขาสูงและหุบเขาเช่นกัน', 'hǎi yáng dǐ bù yě yǒu gāo shān hé xiá gǔ'),
(1195, '川', 'chuān', '冰川', 'bīng chuān', 'ธารน้ำแข็ง', '地球的南北两极布满了冰川。', 'ขั้วโลกเหนือและใต้ของโลกปกคลุมด้วยธารน้ำแข็ง', 'dì qiú de nán běi liǎng jí bù mǎn le bīng chuān'),
(1196, '扬', 'yáng', '飘扬', 'piāo yáng', 'โบกสะบัด', '运动员手里的国旗在迎风飘扬。', 'ธงชาติในมือนักกีฬาโบกสะบัดต้านลม', 'yùn dòng yuán shǒu lǐ de guó qí zài yíng fēng piāo yáng'),
(1197, '奔', 'bēn', '奔跑', 'bēn pǎo', 'วิ่ง/ควบ', '这名运动员正在跑道上飞速奔跑。', 'นักกีฬาคนนี้กำลังวิ่งอย่างรวดเร็วบนลู่วิ่ง', 'zhè míng yùn dòng yuán zhèng zài pǎo dào shàng fēi sù bēn pǎo'),
(1198, '碧', 'bì', '碧绿', 'bì lǜ', 'เขียวมรกต', '平静的湖面像一颗碧绿的宝石。', 'ผิวทะเลสาบที่นิ่งสงบเหมือนอัญมณีสีเขียวมรกต', 'píng jìng de hú miàn xiàng yì kē bì lǜ de bǎo shí'),
(1199, '部', 'bù', '部队', 'bù duì', 'กองทหาร/กองกำลัง', '一位军官正在给他的部队下命令。', 'นายทหารคนหนึ่งกำลังออกคำสั่งให้กองกำลังของเขา', 'yí wèi jūn guān zhèng zài gěi tā de bù duì xià mìng lìng'),
(1200, '劲', 'jìn', '使劲', 'shǐ jìn', 'ออกแรง', '再使劲推一把，车子就能发动了。', 'ออกแรงดันอีกทีเดียว รถก็จะสตาร์ทติดแล้ว', 'zài shǐ jìn tuī yì bǎ, chē zi jiù néng fā dòng le');
